package ai.fitnova.service;
import ai.fitnova.api.ApiDtos.*; import ai.fitnova.domain.*; import ai.fitnova.repo.ReadinessRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service @RequiredArgsConstructor public class ReadinessService {private final ReadinessRepository entries;
 @Transactional public ReadinessView create(User u,ReadinessRequest r){int score=calculate(r);String condition=Optional.ofNullable(r.currentCondition()).orElse("").toLowerCase();boolean safety=List.of("significant pain","dizziness","fever","breathing difficulty","recent significant injury").stream().anyMatch(condition::contains);if(safety)score=Math.min(score,25);ReadinessEntry e=new ReadinessEntry();e.setUser(u);e.setSleepHours(r.sleepHours());e.setSleepQuality(r.sleepQuality());e.setEnergy(r.energy());e.setSoreness(r.soreness());e.setMood(r.mood());e.setStress(r.stress());e.setAvailableMinutes(r.availableMinutes());e.setCurrentCondition(r.currentCondition());e.setRestingHeartRate(r.restingHeartRate());e.setHrv(r.hrv());e.setScore(score);e.setRecommendation(safety?"Skip strenuous training and consider appropriate professional guidance if symptoms are significant or persistent.":recommendation(score));return view(entries.save(e));}
 public int calculate(ReadinessRequest r){int score=50+(int)Math.round((r.sleepHours().doubleValue()-7)*4)+(r.sleepQuality()-3)*6+(r.energy()-3)*7-(r.soreness()-3)*6+(r.mood()-3)*4-(r.stress()-3)*5;return Math.max(0,Math.min(100,score));}
 public ReadinessView latest(User u){return entries.findFirstByUserIdOrderByEntryDateDescIdDesc(u.getId()).map(this::view).orElse(null);} public List<ReadinessView> trend(User u){return entries.findTop30ByUserIdOrderByEntryDateDescIdDesc(u.getId()).stream().map(this::view).toList();}
 public ReadinessView view(ReadinessEntry e){String status=e.getScore()>=75?"READY":e.getScore()>=50?"GO LIGHT":"RECOVER";return new ReadinessView(e.getId(),e.getEntryDate(),e.getScore(),status,e.getRecommendation(),e.getAvailableMinutes());}
 private String recommendation(int score){return score>=75?"Your recovery signals support a moderate session today.":score>=50?"Keep today's session lighter and controlled.":"Recovery-focused movement or rest is recommended.";}}
